BLOB = r'''{"data/dashboard.json": "", "data/budget.json": "", "scripts/registry.json": "", "index.html": ""}'''

"""Обновление данных дашборда до версии 07.08.2026.

Положите в корень репозитория Macroeconomics и запустите:
    python update_dashboard_data.py
Затем: git add . && git commit -m "data: обновление 07.08.2026" && git push
"""
import base64, json, os
for path, b64 in json.loads(BLOB).items():
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    open(path, "wb").write(base64.b64decode(b64))
    print("обновлён", path)
print("Готово: 44 показателя, 5 разделов.")
